use crate::types::{LineColour,LineMetadata,ListType};
#[derive(Debug,Clone,Copy,PartialEq,Eq)]pub enum ModificationKind{InsertText,DeleteText,Other}
#[derive(Debug,Clone,PartialEq,Eq)]pub struct MetadataSnapshot{pub lines:Vec<LineMetadata>}
#[derive(Debug,Clone,PartialEq,Eq)]pub struct MetadataOverlay{lines:Vec<LineMetadata>}
impl Default for MetadataOverlay{fn default()->Self{Self::new(1)}}
impl MetadataOverlay{pub fn new(n:usize)->Self{Self{lines:vec![LineMetadata::default();n.max(1)]}}pub fn from_lines(mut lines:Vec<LineMetadata>)->Self{if lines.is_empty(){lines.push(LineMetadata::default())}Self{lines}}pub fn len(&self)->usize{self.lines.len()}pub fn is_empty(&self)->bool{self.lines.is_empty()}pub fn get(&self,i:usize)->Option<&LineMetadata>{self.lines.get(i)}pub fn get_mut(&mut self,i:usize)->Option<&mut LineMetadata>{self.lines.get_mut(i)}pub fn as_slice(&self)->&[LineMetadata]{&self.lines}pub fn snapshot(&self)->MetadataSnapshot{MetadataSnapshot{lines:self.lines.clone()}}pub fn restore(&mut self,s:MetadataSnapshot){*self=Self::from_lines(s.lines)}pub fn on_insert(&mut self,line:usize,n:usize){if n>0{let at=(line+1).min(self.lines.len());self.lines.splice(at..at,std::iter::repeat_with(LineMetadata::default).take(n));}}pub fn on_delete(&mut self,line:usize,n:usize){if n==0||self.lines.len()<2{return}let a=(line+1).min(self.lines.len());let b=(a+n).min(self.lines.len());if a<b{self.lines.drain(a..b);}if self.lines.is_empty(){self.lines.push(LineMetadata::default())}}pub fn on_modified(&mut self,line:usize,kind:ModificationKind,lines_added:isize){match kind{ModificationKind::InsertText if lines_added>0=>self.on_insert(line,lines_added as usize),ModificationKind::DeleteText if lines_added<0=>self.on_delete(line,(-lines_added) as usize),_=>{}}}pub fn sync_to_line_count(&mut self,n:usize){let n=n.max(1);if n>self.lines.len(){self.lines.extend(std::iter::repeat_with(LineMetadata::default).take(n-self.lines.len()))}else{self.lines.truncate(n)}}pub fn inserted_newlines(&mut self,line:usize,n:usize){self.on_insert(line,n)}pub fn deleted_newlines(&mut self,line:usize,n:usize){self.on_delete(line,n)}pub fn apply_colour(&mut self,start:usize,end:usize,c:LineColour){if self.lines.is_empty()||start>end{return}let end=end.min(self.lines.len()-1);let toggle=(start..=end).all(|i|self.lines[i].colour==c);for i in start..=end{self.lines[i].colour=if toggle{LineColour::None}else{c}}}pub fn clear_colour(&mut self,start:usize,end:usize){if self.lines.is_empty()||start>end{return}for i in start..=end.min(self.lines.len()-1){self.lines[i].colour=LineColour::None}}pub fn toggle_checked(&mut self,line:usize)->Option<bool>{let m=self.lines.get_mut(line)?;if m.list_type!=ListType::Check{return None}m.checked=!m.checked;Some(m.checked)}}
